import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Extracts — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"extracts-04-troubleshooting-and-faqs.md","filePath":"extracts-04-troubleshooting-and-faqs.md"}'),s={name:"extracts-04-troubleshooting-and-faqs.md"};function o(n,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="extracts-—-troubleshooting-faqs" tabindex="-1">Extracts — Troubleshooting &amp; FAQs <a class="header-anchor" href="#extracts-—-troubleshooting-faqs" aria-label="Permalink to &quot;Extracts — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, edge cases, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="what-file-format-does-my-transcript-need-to-be-in" tabindex="-1">What file format does my transcript need to be in? <a class="header-anchor" href="#what-file-format-does-my-transcript-need-to-be-in" aria-label="Permalink to &quot;What file format does my transcript need to be in?&quot;">​</a></h3><p>Transcripts must be uploaded as files — there is no paste field. Audio and video files are not supported; these need to be transcribed first by a recording platform (such as Fireflies or Gong) before being brought into Lodestone. Competitive Intelligence reports can also be sent to Extracts using the Extract Features from Report action in the Intel module — no file upload required for those.</p><h3 id="how-long-does-analysis-take-after-i-upload-a-transcript" tabindex="-1">How long does analysis take after I upload a transcript? <a class="header-anchor" href="#how-long-does-analysis-take-after-i-upload-a-transcript" aria-label="Permalink to &quot;How long does analysis take after I upload a transcript?&quot;">​</a></h3><p>Processing time varies depending on the length of the transcript. A processing indicator is shown while analysis is in progress. There is no notification when Extracts are ready — you&#39;ll need to return to the Extracts module and check manually.</p><h3 id="can-i-edit-an-extract-before-promoting-it-to-my-backlog" tabindex="-1">Can I edit an Extract before promoting it to my backlog? <a class="header-anchor" href="#can-i-edit-an-extract-before-promoting-it-to-my-backlog" aria-label="Permalink to &quot;Can I edit an Extract before promoting it to my backlog?&quot;">​</a></h3><p>No. Extracts are not editable before promotion. The AI-generated Feature Name and Description carry over as-is when you add an Extract to the backlog. If you want to refine them, add the Extract to the backlog first and then edit the Feature from the Feature Detail page.</p><h3 id="can-i-recover-a-dismissed-extract" tabindex="-1">Can I recover a dismissed Extract? <a class="header-anchor" href="#can-i-recover-a-dismissed-extract" aria-label="Permalink to &quot;Can I recover a dismissed Extract?&quot;">​</a></h3><p>No. Dismissing an Extract permanently deletes it — there is no undo, no recycle bin, and no recovery path. If the idea matters, you&#39;ll need to create it manually as a Feature in the backlog.</p><h3 id="do-extracts-automatically-get-added-to-my-backlog" tabindex="-1">Do Extracts automatically get added to my backlog? <a class="header-anchor" href="#do-extracts-automatically-get-added-to-my-backlog" aria-label="Permalink to &quot;Do Extracts automatically get added to my backlog?&quot;">​</a></h3><p>No. Every Extract requires an explicit decision. Nothing moves to your backlog without you actively choosing to add it. This is intentional — it keeps your backlog clean and ensures every Feature in it has been consciously reviewed.</p><h3 id="what-happens-to-the-transcript-after-extracts-are-generated" tabindex="-1">What happens to the transcript after Extracts are generated? <a class="header-anchor" href="#what-happens-to-the-transcript-after-extracts-are-generated" aria-label="Permalink to &quot;What happens to the transcript after Extracts are generated?&quot;">​</a></h3><p>The original transcript is not stored in Lodestone. Only the generated Extracts are retained. If you need to refer back to the source transcript, you&#39;ll find it in the platform you uploaded or imported it from (e.g. Fireflies or Gong).</p><h3 id="can-multiple-team-members-review-the-same-set-of-extracts" tabindex="-1">Can multiple team members review the same set of Extracts? <a class="header-anchor" href="#can-multiple-team-members-review-the-same-set-of-extracts" aria-label="Permalink to &quot;Can multiple team members review the same set of Extracts?&quot;">​</a></h3><p>Yes. Extracts are visible to all workspace members, not just the user who uploaded the transcript. Any member can add an Extract to the backlog or dismiss it.</p><h3 id="the-ai-surfaced-a-lot-of-irrelevant-extracts-is-something-wrong" tabindex="-1">The AI surfaced a lot of irrelevant Extracts. Is something wrong? <a class="header-anchor" href="#the-ai-surfaced-a-lot-of-irrelevant-extracts-is-something-wrong" aria-label="Permalink to &quot;The AI surfaced a lot of irrelevant Extracts. Is something wrong?&quot;">​</a></h3><p>No. The AI is designed to surface everything that might represent an opportunity — noise is expected and intentional. Its job is comprehensive signal capture, not pre-filtering. Your job is to review and decide what matters. Dismiss the irrelevant ones and keep what&#39;s useful.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="i-uploaded-a-transcript-but-no-extracts-appeared" tabindex="-1">I uploaded a transcript but no Extracts appeared <a class="header-anchor" href="#i-uploaded-a-transcript-but-no-extracts-appeared" aria-label="Permalink to &quot;I uploaded a transcript but no Extracts appeared&quot;">​</a></h3><p>A few things to check:</p><ul><li>Make sure the transcript is in a supported file format</li><li>Check that the transcript contains substantive content — very short or sparse transcripts may not produce Extracts</li><li>Check the processing indicator — if it&#39;s still showing, analysis is still in progress. Refresh the page once it has completed.</li></ul><h3 id="my-extracts-don-t-reflect-what-was-actually-discussed-in-the-meeting" tabindex="-1">My Extracts don&#39;t reflect what was actually discussed in the meeting <a class="header-anchor" href="#my-extracts-don-t-reflect-what-was-actually-discussed-in-the-meeting" aria-label="Permalink to &quot;My Extracts don&#39;t reflect what was actually discussed in the meeting&quot;">​</a></h3><p>This usually comes down to transcript quality. If the transcription itself contains errors, missing segments, or unclear speaker attribution, the Extracts will reflect those gaps. Try using a higher-quality transcript source if available.</p><p>It&#39;s also worth remembering that the AI surfaces ideas based on what appears in the text — if something important was said but didn&#39;t make it into the transcript clearly, it won&#39;t appear as an Extract.</p><h3 id="i-accidentally-dismissed-an-extract-i-wanted-to-keep" tabindex="-1">I accidentally dismissed an Extract I wanted to keep <a class="header-anchor" href="#i-accidentally-dismissed-an-extract-i-wanted-to-keep" aria-label="Permalink to &quot;I accidentally dismissed an Extract I wanted to keep&quot;">​</a></h3><p>There is no recovery path. Dismissed Extracts are permanently deleted. You&#39;ll need to create the Feature manually from the backlog. Going forward, take a moment to read each Extract carefully before dismissing — the action is irreversible.</p><h3 id="fireflies-or-gong-transcripts-aren-t-appearing-in-the-import-list" tabindex="-1">Fireflies or Gong transcripts aren&#39;t appearing in the import list <a class="header-anchor" href="#fireflies-or-gong-transcripts-aren-t-appearing-in-the-import-list" aria-label="Permalink to &quot;Fireflies or Gong transcripts aren&#39;t appearing in the import list&quot;">​</a></h3><p>If you can&#39;t see meetings when trying to import from Fireflies or Gong:</p><p><strong>Fireflies:</strong></p><ul><li>Confirm the Fireflies integration is connected in Settings &gt; Integrations</li><li>Check that the meeting exists in your Fireflies account and the transcript has been generated there first</li><li>Try disconnecting and reconnecting the integration if the issue persists</li></ul><p><strong>Gong:</strong></p><ul><li>Confirm the Gong integration is connected in Settings &gt; Integrations</li><li>Check that the accounts you selected during initial setup include the user whose calls you&#39;re looking for — if a colleague&#39;s calls aren&#39;t visible, their account may not have been selected during setup</li><li>To change which accounts are included, revisit the Gong integration settings</li></ul><hr><p><em>This is version 1 of the Extracts documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',38)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
